<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref, shallowRef } from 'vue'
import type { Chapter, PlanningPackageProposal } from '../../../desktop/src/contracts/index'
import type { ChapterEventPreview } from '../../../desktop/src/contracts/planning/types'
import { writing, points, type BookApi, type Job, type Model } from '../api/writing'
import { messageOf } from '../api/http'
const props = defineProps<{ api: BookApi; chapters: Chapter[]; locked: boolean }>()
const emit = defineEmits<{ adopted: []; 'refresh-wallet': [] }>()
const proposal = ref<PlanningPackageProposal | null>(null), models = ref<Model[]>([]), model = ref(''), volume = ref(1), chapter = ref(0), job = ref<Job | null>(null), busy = ref(false), error = ref(''), notice = ref('')
const preview = shallowRef<{ title: string; lines: string[]; text?: string; apply: () => Promise<void> } | null>(null)
const eventSource = ref<ChapterEventPreview | null>(null), eventForm = reactive({ time: '', characters: '', location: '', event: '', result: '' })
let alive = true, timer: ReturnType<typeof setTimeout> | undefined, operation = crypto.randomUUID(), operationInput = ''
const running = computed(() => !!job.value && ['queued', 'running'].includes(job.value.status))
const selectedModel = computed(() => models.value.find(m => m.id === model.value))
const fee = computed(() => { const p = selectedModel.value?.price.policy; return p?.mode === 'request' ? `${points(p.points)} 积分 / 任务` : p?.mode === 'tokens' ? `输入 ${points(p.inputPerMillion)} / 输出 ${points(p.outputPerMillion)} 积分每百万 tokens` : p?.mode === 'provider-tokens' ? `按供应商实际用量折算 · 1 美元余额 = ${p.usdToCny} 元` : '尚未配置计费' })
async function read() { proposal.value = await props.api.planningDraft() }
async function poll(id: string) { clearTimeout(timer); try { const next = await props.api.job(id); if (!alive) return; job.value = next; if (['queued', 'running'].includes(next.status)) timer = setTimeout(() => { void poll(id) }, 1800); else { await read(); emit('refresh-wallet') } } catch (e) { if (alive) error.value = messageOf(e) } }
async function generate(kind: 'planning' | 'skeleton' | 'chapter-detail') { if (busy.value || running.value || props.locked) return; busy.value = true; error.value = ''; const request = kind === 'planning' ? {} : { proposalId: proposal.value!.id, ...(kind === 'chapter-detail' ? { volume: volume.value } : {}) }; const key = JSON.stringify([kind, model.value, request]); if (key !== operationInput) { operationInput = key; operation = crypto.randomUUID() }
  try { const id = await props.api.generatePlanning(operation, model.value, kind, request); operation = crypto.randomUUID(); await poll(id); emit('refresh-wallet') } catch (e) { error.value = messageOf(e) } finally { busy.value = false } }
async function stop() { if (!job.value) return; try { await props.api.cancel(job.value.id); await poll(job.value.id) } catch (e) { error.value = messageOf(e) } }
async function prepare(kind: 'total' | 'volumes' | 'volume' | 'skeleton') { if (!proposal.value || props.locked) return; busy.value = true; error.value = ''
  try { const id = proposal.value.id
    if (kind === 'total') { const p = await props.api.previewTotal(id); preview.value = { title: '采用全局总纲', lines: [`现有总纲 ${p.current.characterCount} 字符；候选 ${p.candidate.characterCount} 字符。`, `影响 ${p.affected.chapterOutlines} 份章纲及 ${p.affected.confirmedVolumes} 个已确认分卷，请采用后重新核对。`], text: `${p.current.excerpt ? `当前：\n${p.current.excerpt}\n\n` : ''}候选：\n${p.candidate.excerpt}`, apply: () => props.api.adoptTotal(p) } }
    if (kind === 'volumes') { const p = await props.api.previewVolumes(id); if (p.conflicts.length) throw new Error(p.conflicts.join('；')); preview.value = { title: '采用分卷结构', lines: p.actions.map(a => `第 ${a.order} 卷：${a.fromTitle || '新分卷'} → ${a.toTitle}`), apply: () => props.api.adoptVolumes(p) } }
    if (kind === 'volume') { const p = await props.api.previewVolume(id, volume.value); preview.value = { title: `采用第 ${p.order} 卷卷纲`, lines: [`影响 ${p.affected.chapterOutlines} 份章纲，采用后需要重新核对确认。`], text: `当前：\n${p.current.excerpt}\n\n候选：\n${p.candidate.excerpt}`, apply: () => props.api.adoptVolume(p) } }
    if (kind === 'skeleton') { const p = await props.api.previewSkeleton(id, volume.value); if (!p.canAdopt) throw new Error(p.reason); preview.value = { title: '采用章节骨架', lines: p.entries.map(e => `第 ${e.chapter} 章 · ${e.title}${e.reasons.length ? `：${e.reasons.join('；')}` : ''}`), apply: () => props.api.adoptSkeleton(p.token) } }
  } catch (e) { error.value = messageOf(e) } finally { busy.value = false } }
async function prepareSeed(kind: 'characters' | 'world' | 'power' | 'cheat') { if (!proposal.value || props.locked) return; busy.value = true; error.value = ''; try {
  if (kind === 'characters') { const p = await props.api.previewSeed(kind, proposal.value.id); if (p.conflicts.length) throw new Error(p.conflicts.join('；')); preview.value = { title: '核对人物种子', lines: p.actions.map(a => `${a.name} · ${a.candidate.role} · ${a.candidate.arcSeed}`), apply: () => props.api.adoptSeed(kind, p) } }
  else { const p = await props.api.previewSeed(kind, proposal.value.id); preview.value = { title: { world: '核对世界种子', power: '核对力量体系', cheat: '核对特殊优势' }[kind], lines: ['确认候选与现有设定一致。空候选表示此次不采用新的内容。'], text: `当前：\n${p.current.excerpt || '尚未设置'}\n\n候选：\n${p.candidate.excerpt || '不设置此能力'}`, apply: () => props.api.adoptSeed(kind, p) } }
} catch (e) { error.value = messageOf(e) } finally { busy.value = false } }
async function inspectChapter() { if (!proposal.value || !chapter.value) return; busy.value = true; error.value = ''; try { const p = await props.api.previewChapterEvents(proposal.value.id, chapter.value); eventSource.value = p; Object.assign(eventForm, { time: '', characters: p.candidate.characters.join('、'), location: p.candidate.location, event: p.candidate.coreEvent, result: p.candidate.plannedResult }) } catch (e) { error.value = messageOf(e) } finally { busy.value = false } }
async function prepareChapter() { if (!eventSource.value || props.locked) return; busy.value = true; error.value = ''; try { const source = eventSource.value, p = await props.api.previewChapterAdoption(source.proposalId, source.chapterId, [{ ...eventForm, characters: eventForm.characters.split(/[、,，\n]/).map(x => x.trim()).filter(Boolean) }]); preview.value = { title: '联合采用章纲与事件', lines: [`本章已有 ${p.existingEventCount} 条事件。${p.replacesChapter ? '此次将更新章纲。' : '此次将建立章纲。'}`, `${eventForm.time} · ${eventForm.characters} · ${eventForm.location}`, `${eventForm.event} → ${eventForm.result}`], text: p.chapterContent, apply: () => props.api.adoptChapterEvents(p.token) } } catch (e) { error.value = messageOf(e) } finally { busy.value = false } }
async function commit() { if (!preview.value || props.locked) return; busy.value = true; try { await preview.value.apply(); preview.value = null; eventSource.value = null; await read(); notice.value = '已采用。请核对正式文档与依赖提示，再确认大纲。'; emit('adopted') } catch (e) { error.value = messageOf(e) } finally { busy.value = false } }
onMounted(async () => { try { await read(); models.value = await writing.models(); model.value = models.value[0]?.id || ''; const latest = (await props.api.jobs()).find(j => ['planning', 'skeleton', 'chapter-detail'].includes(j.kind)); if (latest) await poll(latest.id) } catch (e) { error.value = messageOf(e) } })
onBeforeUnmount(() => { alive = false; clearTimeout(timer) })
</script>
<template><details class="planning-candidates paper-card"><summary>AI 谋篇 · 从蓝图到章纲</summary><p>基于已保存的定书与设定生成候选。每一步均由你核对采用；正式稿不会自动改写。</p><p v-if="locked" class="warning">请先保存当前大纲，再生成或采用候选。</p><p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="notice" class="success" role="status">{{ notice }}</p><div class="form-row"><label>谋篇模型<select v-model="model"><option value="">选择站长提供的模型</option><option v-for="item in models" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><p>{{ fee }}</p></div><div class="button-row"><button :disabled="busy || running || locked || !selectedModel || selectedModel.price.policy.mode === 'unconfigured'" @click="generate('planning')">生成整书规划候选</button><button v-if="running" @click="stop">停止谋篇</button><button :disabled="busy" @click="read().catch(e => error = messageOf(e))">重读候选</button></div><p v-if="job" class="muted">{{ running ? '正在谋篇，可离开页面稍后查看。' : job.status === 'succeeded' ? '谋篇候选已完成。' : '任务未完成。请核对已保存的题材、资料和上层大纲；已有候选保留。' }} 已扣 {{ points(job.billing.charged) }} · 预留 {{ points(job.billing.reserved) }} 积分。<span v-if="job.billing.needsReconciliation">用量待站长核对。</span></p><template v-if="proposal"><h3>{{ proposal.totalOutline.title }}</h3><p class="muted">先逐项核对人物、世界、力量与特殊优势，再采用总纲。</p><div class="button-row"><button v-for="(label, key) in { characters: '人物种子', world: '世界种子', power: '力量体系', cheat: '特殊优势' }" :key="key" :disabled="busy || locked || running" @click="prepareSeed(key)">核对{{ label }}</button></div><p>{{ proposal.blueprint.premise }}</p><details><summary>查看世界蓝图与总纲候选</summary><p>{{ proposal.blueprint.worldView }}</p><p v-for="person in proposal.blueprint.characters" :key="person.name">{{ person.name }} · {{ person.role }} · {{ person.arcSeed }}</p><pre class="candidate-text">{{ proposal.totalOutline.content }}</pre></details><div class="button-row"><button :disabled="busy || locked || running" @click="prepare('total')">预览采用总纲</button><button :disabled="busy || locked || running" @click="prepare('volumes')">预览采用分卷结构</button></div><label>候选分卷<select v-model.number="volume"><option v-for="v in proposal.volumes" :key="v.order" :value="v.order">第 {{ v.order }} 卷 · {{ v.title }}</option></select></label><p>{{ proposal.volumes.find(v => v.order === volume)?.summary }}</p><div class="button-row"><button :disabled="busy || locked || running" @click="prepare('volume')">预览采用卷纲</button><button :disabled="busy || locked || running || !selectedModel || selectedModel.price.policy.mode === 'unconfigured'" @click="generate('skeleton')">生成章节骨架</button><button :disabled="busy || locked || running || !proposal.chapterSkeleton" @click="prepare('skeleton')">预览采用章节骨架</button><button :disabled="busy || locked || running || !proposal.chapterSkeleton || !selectedModel || selectedModel.price.policy.mode === 'unconfigured'" @click="generate('chapter-detail')">生成本卷章纲候选</button></div><details v-if="proposal.chapterSkeleton"><summary>查看章节骨架</summary><article v-for="c in proposal.chapterSkeleton.chapters.filter(c => c.volume === volume)" :key="c.chapter"><h4>第 {{ c.chapter }} 章 · {{ c.title }}</h4><p>{{ c.coreEvent }} → {{ c.result }}</p></article></details><div v-if="proposal.chapterDetails?.length"><label>核对章纲候选<select v-model.number="chapter"><option :value="0">选择已建立的章节</option><option v-for="c in chapters" :key="c.id" :value="c.id">第 {{ c.position }} 章 · {{ c.title }}</option></select></label><button :disabled="busy || locked || !chapter" @click="inspectChapter">核对事件与章纲</button></div><form v-if="eventSource" class="paper-card" @submit.prevent="prepareChapter"><h3>补全事件四要素</h3><p v-for="f in eventSource.findings" :key="f.code" class="warning">{{ f.message }}</p><pre class="candidate-text">{{ eventSource.candidate.beats.join('\n') }}</pre><label>候选事件时间<input v-model="eventForm.time" required></label><label>候选事件人物<input v-model="eventForm.characters" required></label><label>候选事件地点<input v-model="eventForm.location" required></label><label>候选事件内容<textarea v-model="eventForm.event" required></textarea></label><label>候选事件结果<textarea v-model="eventForm.result" required></textarea></label><button :disabled="busy || locked">预览联合采用</button></form></template><p v-else class="muted">尚无规划候选。先填写定书题材，并在设定的作者札记或资料卡中保存创作设想。</p><div v-if="preview" class="modal-backdrop"><section v-dialog="() => { if (!busy) preview = null }" class="paper-card dialog-card" role="dialog" aria-modal="true" aria-label="核对规划采用"><h2>{{ preview.title }}</h2><p v-for="line in preview.lines" :key="line">{{ line }}</p><pre v-if="preview.text" class="candidate-text">{{ preview.text }}</pre><div class="button-row"><button :disabled="busy" @click="preview = null">返回核对</button><button class="primary" :disabled="busy || locked" @click="commit">确认采用</button></div></section></div></details></template>
